package com.exito.chop;
import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;
final class MidiIO {
 static final class Note {final double start,end;final int pitch,velocity,channel;Note(double a,double b,int p,int v){this(a,b,p,v,0);}Note(double a,double b,int p,int v,int c){start=a;end=b;pitch=p;velocity=v;channel=Math.max(0,Math.min(15,c));}}
 static final class Event {final long tick;final byte[] bytes;Event(long t,byte...b){tick=t;bytes=b;}}
 static void variable(OutputStream out,long value)throws IOException{if(value<0||value>0xfffffff)throw new IOException("MIDI demasiado largo");long b=value&127;while((value>>=7)>0)b=(b<<8)|((value&127)|128);for(;;){out.write((int)(b&255));if((b&128)==0)break;b>>=8;}}
 static byte[] file(List<Note> n,int bpm,String title)throws IOException{return file(n,bpm,title,-1);}static byte[] file(List<Note> notes,int bpm,String title,int program)throws IOException{bpm=Math.max(20,Math.min(400,bpm));ArrayList<Event> ev=new ArrayList<>();int tempo=60000000/bpm;ev.add(new Event(0,(byte)255,(byte)81,(byte)3,(byte)(tempo>>16),(byte)(tempo>>8),(byte)tempo));ev.add(new Event(0,(byte)255,(byte)88,(byte)4,(byte)4,(byte)2,(byte)24,(byte)8));if(program>=0)ev.add(new Event(0,(byte)192,(byte)program));for(Note n:notes){if(n.end<=n.start||n.pitch<0||n.pitch>127)continue;long a=Math.max(0,Math.round(n.start*bpm*8)),b=Math.max(a+1,Math.round(n.end*bpm*8));ev.add(new Event(a,(byte)(144|n.channel),(byte)n.pitch,(byte)Math.max(1,Math.min(127,n.velocity))));ev.add(new Event(b,(byte)(128|n.channel),(byte)n.pitch,(byte)0));}ev.sort((a,b)->{int c=Long.compare(a.tick,b.tick);return c==0?Integer.compare(priority(a),priority(b)):c;});ByteArrayOutputStream track=new ByteArrayOutputStream();byte[] name=title.getBytes(StandardCharsets.UTF_8);variable(track,0);track.write(new byte[]{(byte)255,3});variable(track,name.length);track.write(name);long last=0;for(Event event:ev){variable(track,event.tick-last);track.write(event.bytes);last=event.tick;}track.write(new byte[]{0,(byte)255,47,0});ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(out);d.writeBytes("MThd");d.writeInt(6);d.writeShort(0);d.writeShort(1);d.writeShort(480);d.writeBytes("MTrk");d.writeInt(track.size());track.writeTo(out);return out.toByteArray();}
 static int priority(Event e){int s=e.bytes[0]&255;return s==255?0:(s&240)==192?1:(s&240)==128?2:3;}
 static byte[] sampleDump(short[] mono,int rate,int sample)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{(byte)240,126,0,1,(byte)(sample&127),(byte)(sample>>7),12});int period=(int)Math.round(1e9/rate);for(int n:new int[]{period,mono.length,0,Math.max(0,mono.length-1)})for(int i=0;i<3;i++)out.write((n>>(7*i))&127);out.write(127);out.write(247);for(int at=0,packet=0;at<mono.length;at+=60,packet++){out.write(new byte[]{(byte)240,126,0,2,(byte)(packet&127)});int check=126^2^(packet&127);for(int i=0;i<60;i++){int word=at+i<mono.length?(mono[at+i]>>4)+2048:2048,a=(word>>5)&127,b=(word&31)<<2;out.write(a);out.write(b);check^=a^b;}out.write(check&127);out.write(247);}return out.toByteArray();}
}
